head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > showCustomFilterReset]<br/>CustomFilter 팝업창에 '초기화' 버튼을 표시할지 설정합니다.",
    "validation" : [
        "true 설정 시, CustomFilter 팝업창의 하단 버튼 그룹에 '초기화' 버튼을 추가하여 표시합니다.",
        "false 설정 시, CustomFilter 팝업창의 하단 버튼 그룹에 '확인','취소' 버튼만 표시합니다.",
        "미설정 시, CustomFilter 팝업창의 하단 버튼 그룹에 '확인','취소' 버튼만 표시합니다.",
        "CustomFilter 팝업창에서 '초기화' 버튼 클릭 시 해당 Column 에 적용되어 있는 필터값으로 복원됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_showCustomFilterReset(gdl_boolean getText → '' / 'true' / 'false') 을 렌더 시 grid 속성으로 반영
//  - Header Column 은 useFilter="true" (필터 아이콘 상시 표시) / useFilterList 미설정 → 필터 아이콘 클릭 시 CustomFilter 팝업 직접 표시
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제 (Target 재생성으로 팝업 등 상태 초기화)
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 렌더 전제(con) : showCustomFilterReset (gdl_boolean → '' / 'true' / 'false')
    let vReset = con_showCustomFilterReset.getText();

    let properties = {};
    if (vReset === 'true') { properties.showCustomFilterReset = true; }
    else if (vReset === 'false') { properties.showCustomFilterReset = false; }

    // 상태 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] showCustomFilterReset = ' + (vReset === '' ? '(미설정=false)' : vReset)
        + '\n[전제] col1~col4 Header = useFilter=true (필터 아이콘 有), useFilterList 미설정 -> 아이콘 클릭 시 CustomFilter 팝업 직접 표시'
        + '\n[절차] useFilter 컬럼 헤더의 필터 아이콘 클릭해 CustomFilter 팝업 연 뒤 (버튼 확인) 클릭'
        + '\n[확인] 하단 버튼 그룹 구성 : true=초기화+확인+취소(3버튼) / false·미설정=확인+취소(2버튼)'
        + '\n[참고] 초기화 복원 : 팝업에 필터값 입력 후 확인으로 적용 -> 재오픈 후 값 변경 -> 초기화 클릭 시 적용된 필터값으로 복원"', '', 'label1');

    // dataList 생성 (4행, col1~col4)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    let cList = $c.gcm.createCList(properties);
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    // useFilter="true" Header Column(col1~col4) 인라인 구성한 gridView 동적 생성
    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="showCustomFilterReset 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="hrow1">';
    s += '<w2:column width="130" style="" inputType="text" id="hcol1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="hcol2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="hcol3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="hcol4" value="col4" useFilter="true"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="brow1">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// [확인] CustomFilter 팝업 하단 버튼 그룹 확인 :
//  사용자가 useFilter=true 컬럼의 필터 아이콘을 클릭해 CustomFilter 팝업을 연 뒤 실행.
//  (필터 아이콘 클릭 자체는 사용자 액션 → 별도 트리거 버튼 생성하지 않음)
//  buttonGroup(.w2grid_customFilter_buttonGroup) 의 버튼(.w2grid_customFilter_button, textbox) 라벨/개수와
//  '초기화' 버튼(id 패턴 _btnReset_) 존재 여부를 읽어 출력.
scwin.btn_checkFilterButtons_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");

    let popup = document.querySelector(".w2grid_customFilter");
    if (!popup) {
        scb.setReturnValue("열린 CustomFilter 팝업이 없습니다. useFilter 컬럼 헤더의 필터 아이콘을 먼저 클릭하세요.");
        return;
    }

    let group = popup.querySelector(".w2grid_customFilter_buttonGroup");
    let btns = group ? group.querySelectorAll(".w2grid_customFilter_button") : [];
    let labels = [];
    for (let i = 0; i < btns.length; i++) {
        labels.push((btns[i].value || btns[i].textContent || "").trim());
    }
    let hasReset = !!popup.querySelector("[id*='_btnReset_']");

    scb.setReturnValue("[옵션] showCustomFilterReset : " + target1.options.showCustomFilterReset);
    scb.setReturnValue("하단 버튼 그룹 버튼 수 : " + btns.length + " / 버튼 : " + labels.join(", "));
    scb.setReturnValue("'초기화' 버튼(btnReset) 존재 : " + hasReset);
}
